use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    if !number {
        print(text)
        return counter
    }
    let mut n: int = counter
    let parts: Vec<string> = text.split("\n").collect()
    let total: int = parts.len()
    let mut i: int = 0
    for p in parts {
        if !(i == total - 1 && p == "") {
            n += 1
            println("${n:>6}\t${p}")
        }
        i += 1
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in env::args() {
        if first {
            first = false
        } else if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter: int = 0
    let mut status: int = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(status)
    }
}

